// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public {
        c = new EtherCartel();
        c.seedMarket(1000);
    }

    function testFuzz_property(address actor, address ref, uint256 warpTime) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        warpTime = bound(warpTime, c.DRUGS_TO_PRODUCE_1KILO(), 100 * c.DRUGS_TO_PRODUCE_1KILO());

        vm.prank(actor);
        c.getFreeKilo();
        uint256 kilosBefore = c.Kilos(actor);

        vm.warp(block.timestamp + warpTime);
        vm.prank(actor);
        c.collectDrugs(ref);

        assertTrue(c.Kilos(actor) > kilosBefore, "collectDrugs must add newly produced kilos");
    }
}
